INSERT INTO HRMS.AUTH_USERS (USER_ID, USERNAME, EMAIL, FULL_NAME_EN, PASSWORD_HASH, ROLE, EMPLOYEE_ID, EMPLOYEE_CODE,
    FAILED_ATTEMPTS, IS_ACTIVE, IS_LOCKED, MUST_CHANGE_PASSWORD, CREATED_BY)
SELECT HRMS.AUTH_USER_SEQ.NEXTVAL, 'amira.khalil', 'amira.khalil@nilepet.com', 'Amira Khalil', '$2a$10$hQUB2uSOzs0wdGKDt7ESxualytgBdZiKVMlCAqzTgx9ULfD7JUPrO', 'EMPLOYEE', e.EMPLOYEE_ID, e.EMPLOYEE_CODE, 0, TRUE, FALSE, 1, 'SAMPLE5'
